#[must_use]
pub fn find_operation(operation_id: &str) -> Option<&'static OperationSpec> {
    OPERATIONS
        .binary_search_by_key(&operation_id, |operation| operation.operation_id)
        .ok()
        .map(|index| &OPERATIONS[index])
}
